/bin/bash -lc "python - <<'PY'
from decimal import Decimal, getcontext
import csv, json, os, math
from collections import defaultdict, Counter
getcontext().prec = 28
base='/app/data'

def D(x):
    if x is None: return None
    x=x.strip()
    if x=='': return None
    return Decimal(x)

def read_csv(name):
    with open(os.path.join(base,name), newline='') as f:
        return list(csv.DictReader(f))

containers = {r['container_id']: r for r in read_csv('containers.csv')}
skus = {r['sku_id']: r for r in read_csv('skus.csv')}
overrides = {(r['sku_id'], r['container_id']): int(r['allowed']) for r in read_csv('sku_container_overrides.csv')}
companions = read_csv('companion_rules.csv')
min_skus = read_csv('container_minimum_skus.csv')
pair_conflicts = read_csv('pair_conflicts.csv')
wave_rules = read_csv('wave_commitments.csv')
lane_rules = read_csv('lane_commitments.csv')
family_rules = read_csv('family_weight_share_rules.csv')
split_rules = read_csv('sku_split_rules.csv')
customs_caps = {r['customs_window']: r for r in read_csv('customs_window_capacity.csv')}
lane_doc_rules = read_csv('lane_document_rules.csv')
slots = {r['slot_id']: r for r in read_csv('loading_slots.csv')}
handling = {r['container_type']: r for r in read_csv('container_handling_requirements.csv')}
period_caps = {r['period_id']: r for r in read_csv('bay_resource_capacity.csv')}
wave_deadlines = {r['wave']: r for r in read_csv('wave_loading_deadlines.csv')}
with open(os.path.join(base,'config.json')) as f:
    config = json.load(f)

with open('/app/submissions/solution.csv', newline='') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
    headers = reader.fieldnames

violations=[]
checks=[]
covered=[]
uncovered=[]

def add_v(family, rule, key, observed, bound, suggestion):
    violations.append({'family':family,'rule':rule,'key':key,'observed':str(observed),'bound':str(bound),'suggestion':suggestion})

def family(name, status, details):
    covered.append((name,status,details))

# Schema / domains
checks.append(('schema_headers', headers == config['solution_columns']))
if headers "'!= config['"'solution_columns']:
    add_v('schema/nullability and key coverage','solution.csv must use exact schema','header',headers,config['solution_columns'],'Export exactly the configured five columns in the required order.')

allowed_vars={'load','use','schedule'}
load_rows=[]; use_rows=[]; schedule_rows=[]
for i,r in enumerate(rows, start=2):
    var=r['variable']
    if var not in allowed_vars:
        add_v('schema/nullability and key coverage','variable domain','row %d'%i,var,allowed_vars,'Restrict variable to load/use/schedule.')
    q=D(r['quantity'])
    if q is None:
        add_v('schema/nullability and key coverage','quantity non-null','row %d'%i,r['quantity'],'non-null numeric','Populate quantity with an integer value.')
        continue
    if q "'!= q.to_integral_value():
        add_v('"'schema/nullability and key coverage','quantity integrality','row %d'%i,q,'integer','Export integer quantities only.')
    if var=='load':
        load_rows.append((i,r,int(q)))
        if not r['container_id'] or not r['sku_id'] or r['slot_id']:
            add_v('schema/nullability and key coverage','load row nullability/layout',f'row {i}',r,'container_id and sku_id required; slot_id blank', 'For load rows, populate only container_id, sku_id, quantity.')
    elif var=='use':
        use_rows.append((i,r,int(q)))
        if not r['container_id'] or r['sku_id'] or r['slot_id']:
            add_v('schema/nullability and key coverage','use row nullability/layout',f'row {i}',r,'container_id required; sku_id and slot_id blank','For use rows, populate only container_id and quantity.')
    elif var=='schedule':
        schedule_rows.append((i,r,int(q)))
        if not r['container_id'] or r['sku_id'] or not r['slot_id']:
            add_v('schema/nullability and key coverage','schedule row nullability/layout',f'row {i}',r,'container_id and slot_id required; sku_id blank','For schedule rows, populate only container_id, slot_id, quantity.')

# Exact duplicate semantic keys
for name, seq, keyf in [
    ('load', load_rows, lambda x:(x[1]['container_id'],x[1]['sku_id'])),
    ('use', use_rows, lambda x:(x[1]['container_id'],)),
    ('schedule', schedule_rows, lambda x:(x[1]['container_id'],x[1]['slot_id']))
]:
    ctr=Counter(keyf(x) for x in seq)
    dups=[k for k,v in ctr.items() if v>1]
    for k in dups:
        add_v('schema/nullability and key coverage',f'duplicate {name} key',k,ctr[k],1,'Consolidate duplicate semantic rows before export.')

family('schema/nullability and key coverage','checked','exact header, variable domain, nullability pattern, quantity integrality, duplicate semantic keys')

# Identifier domains and cross-linking
load_by_container=defaultdict(lambda: defaultdict(int))
use_by_container=defaultdict(int)
schedule_by_container=defaultdict(lambda: defaultdict(int))
slot_use=defaultdict(int)
containers_with_load=set(); containers_with_schedule=set(); used_containers=set(); sku_totals=defaultdict(int)
for i,r,q in load_rows:
    c=r['container_id']; s=r['sku_id']
    if c not in containers:
        add_v('identifier domains','container_id must exist',f'row {i}:{c}',c,'known container_id','Use a container_id from containers.csv.')
    if s not in skus:
        add_v('identifier domains','sku_id must exist',f'row {i}:{s}',s,'known sku_id','Use a sku_id from skus.csv.')
    load_by_container[c][s]+=q
    containers_with_load.add(c)
    sku_totals[s]+=q
for i,r,q in use_rows:
    c=r['container_id']
    if c not in containers:
        add_v('identifier domains','container_id must exist',f'row {i}:{c}',c,'known container_id','Use a container_id from containers.csv.')
    use_by_container[c]+=q
    if q==1:
        used_containers.add(c)
    elif q"'!=0:
        add_v('"'identifier domains','use quantity binary',f'row {i}:{c}',q,'0 or 1','Use binary use quantities.')
for i,r,q in schedule_rows:
    c=r['container_id']; sl=r['slot_id']
    if c not in containers:
        add_v('identifier domains','container_id must exist',f'row {i}:{c}',c,'known container_id','Use a container_id from containers.csv.')
    if sl not in slots:
        add_v('identifier domains','slot_id must exist',f'row {i}:{sl}',sl,'known slot_id','Use a slot_id from loading_slots.csv.')
    schedule_by_container[c][sl]+=q
    slot_use[sl]+=q
    containers_with_schedule.add(c)
    if q not in (0,1):
        add_v('identifier domains','schedule quantity binary',f'row {i}:{c}/{sl}',q,'0 or 1','Use binary schedule quantities.')
family('identifier domains','checked','container/sku/slot existence plus binary use/schedule domains')

# Frozen/nonanticipative -- no scenario dimension in public data
uncovered.append(('frozen/nonanticipative decisions','not publicly applicable','no scenario or prior-stage fixed-decision tables present under allowed inputs'))

# Compatibility etc
EPS=Decimal(str(config.get('feasibility_tolerance',1e-6)))

def general_compat(sku, cont):
    ok=True
    if sku['temperature_class']=='CHILLED' and cont['reefer']"'!='"'1': ok=False
    if sku['hazmat']=='1' and cont['hazmat_approved']"'!='"'1': ok=False
    if sku['requires_liner']=='1' and cont['has_liner']"'!='"'1': ok=False
    if D(cont['security_tier']) < D(sku['min_security_tier']): ok=False
    return ok

for c, sku_map in load_by_container.items():
    for s,q in sku_map.items():
        if q<=0 or c not in containers or s not in skus: continue
        allowed = overrides.get((s,c))
        permitted = bool(allowed) if allowed is not None else general_compat(skus[s], containers[c])
        if not permitted:
            add_v('identifier domains','SKU-container compatibility',f'load[{c},{s}]',q,'pair must be compatible','Move the SKU to a compatible container or remove the load.')

# cross-linking load/use/schedule
all_conts=set(load_by_container)|set(use_by_container)|set(schedule_by_container)
for c in sorted(all_conts):
    u=use_by_container[c]
    has_pos_load=sum(load_by_container[c].values())>0
    sched_qty=sum(schedule_by_container[c].values())
    if has_pos_load and u "'!= 1:
        add_v('"'schema/nullability and key coverage','loaded container must be used',f'container {c}',u,1,'Add a use row with quantity 1 or remove its load rows.')
    if has_pos_load and sched_qty "'!= 1:
        add_v('"'time/location/readiness/setup/non-overlap','loaded used container must have exactly one slot',f'container {c}',sched_qty,1,'Assign exactly one loading slot to each used container.')
    if u==1 and sched_qty "'!= 1:
        add_v('"'time/location/readiness/setup/non-overlap','used container must have exactly one slot',f'container {c}',sched_qty,1,'Assign exactly one loading slot to each used container.')
    if sched_qty==1 and u "'!= 1:
        add_v('"'schema/nullability and key coverage','scheduled container must be used',f'container {c}',u,1,'Add matching use row or drop the schedule row.')
    if u==1 and not has_pos_load:
        add_v('conservation and inventory','used container should carry positive cargo under min-weight rule',f'container {c}',0,f\">= {containers[c]['min_weight_tons']} tons\",'Load cargo into the used container or remove the use/schedule rows.')

# Conservation and inventory
container_weight=defaultdict(Decimal)
container_pallet=defaultdict(Decimal)
container_family_weight=defaultdict(lambda: defaultdict(Decimal))
for c, sku_map in load_by_container.items():
    for s,q in sku_map.items():
        if s not in skus: continue
        w=D(skus[s]['unit_weight_tons'])*q
        p=D(skus[s]['pallet_positions'])*q
        container_weight[c]+=w
        container_pallet[c]+=p
        container_family_weight[c][skus[s]['sku_family']]+=w

# all required units loaded exactly once
for s, sku in skus.items():
    obs=sku_totals[s]
    req=int(D(sku['required_units']))
    if obs "'!= req:
        add_v('"'conservation and inventory','all required SKU units must be loaded exactly once',f'sku {s}',obs,req,'Rebalance load rows so the exported total matches required_units exactly.')

for c in sorted(used_containers):
    if c not in containers: continue
    wt=container_weight[c]
    pt=container_pallet[c]
    min_w=D(containers[c]['min_weight_tons'])
    max_w=D(containers[c]['max_weight_tons'])
    cap_p=D(containers[c]['pallet_capacity'])
    if wt + EPS < min_w:
        add_v('conservation and inventory','used container minimum loaded weight',f'container {c}',wt,min_w,'Add compatible cargo or do not use the container.')
    if wt - EPS > max_w:
        add_v('conservation and inventory','used container maximum loaded weight',f'container {c}',wt,max_w,'Remove cargo or move it to another container.')
    if pt - EPS > cap_p:
        add_v('conservation and inventory','container pallet capacity',f'container {c}',pt,cap_p,'Reduce palletized cargo in the container.')

for rule in min_skus:
    sku=rule['sku_id']; min_units=D(rule['min_units_per_used_container']); typ=rule['applies_to_container_type']
    for c in sorted(used_containers):
        if c not in containers: continue
        if typ"'!='"'ALL' and containers[c]['container_type']"'!=typ:
            continue
        obs=Decimal(load_by_container[c].get(sku,0))
        if obs + EPS < min_units:
            add_v('"'conservation and inventory','minimum SKU in each used container',f'{c},{sku}',obs,min_units,'Add the required minimum SKU to every affected used container or stop using the container.')

for rule in companions:
    trig=rule['trigger_sku']; comp=rule['companion_sku']; ratio=D(rule['min_companion_per_trigger'])
    for c in sorted(used_containers):
        trig_q=Decimal(load_by_container[c].get(trig,0))
        comp_q=Decimal(load_by_container[c].get(comp,0))
        req=ratio*trig_q
        if comp_q + EPS < req:
            add_v('conservation and inventory','companion ratio in same container',f'{c}: {comp} for {trig}',comp_q,req,'Increase companion cargo in the same container or reduce the trigger SKU there.')

for rule in pair_conflicts:
    a=rule['sku_id']; b=rule['conflict_sku_id']
    for c in sorted(used_containers):
        qa=load_by_container[c].get(a,0)
        qb=load_by_container[c].get(b,0)
        if qa>0 and qb>0:
            add_v('conservation and inventory','conflicting SKU pair cannot share a container',f'{c}: {a} & {b}',f'{qa} and {qb}',0,'Separate the conflicting SKUs into different containers.')

for rule in family_rules:
    fam=rule['sku_family']; share=D(rule['max_weight_share']); typ=rule['applies_to_container_type']
    for c in sorted(used_containers):
        if typ"'!='"'ALL' and containers[c]['container_type']"'!=typ: continue
        total=container_weight[c]
        fam_w=container_family_weight[c].get(fam, Decimal(0))
        req=share*total
        if total>0 and fam_w - EPS > req:
            add_v('"'conservation and inventory','family weight share limit',f'{c},{fam}',fam_w,f'<= {req} ({share} of {total})','Shift some of that family’s weight to other containers or add other compatible cargo.')

for rule in split_rules:
    s=rule['sku_id']; max_per=D(rule['max_units_per_container']); min_dist=int(D(rule['min_distinct_containers']))
    touched=0
    for c in sorted(used_containers):
        q=Decimal(load_by_container[c].get(s,0))
        if q>0:
            touched+=1
        if q - EPS > max_per:
            add_v('conservation and inventory','SKU max units per container',f'{c},{s}',q,max_per,'Split the SKU across more containers.')
    if touched < min_dist:
        add_v('conservation and inventory','SKU minimum distinct containers',f'sku {s}',touched,min_dist,'Spread the SKU across additional containers.')

family('conservation and inventory','checked','exact demand balance, weight/pallet conservation, min-SKU, companions, conflicts, family shares, split rules')

